+export function closedIssueNumber(body: string): number | undefined {
+  const match = new RegExp(`\\b(?:${CLOSING_KEYWORDS})\\s*:?\\s+#(\\d+)\\b`, "i").exec(body);
+  return match ? Number(match[1]) : undefined;
